sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    helpers,
    event,
    imports
}) {
    var customer = api.state.selCompany;
    var device = api.state.selDevice;
    submitItem();

    function submitItem() {
        helpers
            .snHttp(
                "/api/sn_sc/servicecatalog/items/77a7642ec380e210d6d19883e401313a/add_to_cart", {
                    method: "POST",
                    body: {
                        sysparm_quantity: "1",
                        sysparm_requestor: api.context.session.user.sys_id,
                        sysparm_company: customer,
                        sysparm_sys_domain: api.state.selDomain,
                        variables: {
                            customer: customer,
                            device_reference: device,
                        },
                        get_portal_messages: "true",
                        sysparm_no_validation: "true",
                        engagement_channel: "ec",
                    },
                }
            )
            .then(({
                response
            }) => {
                // handle POST request response
                helpers
                    .snHttp("/api/sn_sc/servicecatalog/cart/submit_order", {
                        method: "POST",
                    })
                    .then(({
                        response
                    }) => {
                        api.setState('reqId', response.result.request_id);
                        getRITM();
                    });
            });


    }


    function getRITM() {
        if (api.state.reqId != "") {
            console.log("getritm reqid was " + api.state.reqId);
            const timeoutId = helpers.timing.setTimeout(() => {
                api.data.getRITM.refresh();
            }, 1 * 1000);
        }
    }


}
